return items.map(item => {
  const l = item.json;
  const c = l.contacts || {};
  const wf01 = (l.custom_fields || {}).wf01 || {};
  return {
    json: {
      lead_id: l.id,
      contact_id: l.contact_id,
      nome: c.name || '',
      negocio: c.name || '',
      telefone_normalizado: String(c.phone_number || '').replace(/\D/g, ''),
      mensagem1_enviada_em: wf01.mensagem1_enviada_em || '',
      _custom_fields_raw: l.custom_fields || {}
    }
  };
});

const conv = $json;
const lead = $('Code - Normalizar Leads').item.json;
return {
  json: {
    ...lead,
    conversation_id: conv.id
  }
};

const leads = $('Code - Anexar Conversa').all().map(i => i.json);
const msgs = items.map(i => i.json).filter(m => m && m.body);
const keywords = [
  'automátic', 'automat', 'bot ', 'robô', 'robo ',
  'fora do horário', 'fora de horario',
  'não estamos disponíveis', 'nao estamos disponiveis',
  'obrigado por entrar em contato', 'sua mensagem foi recebida',
  'retornaremos em breve', 'em breve retornaremos',
  'atendimento automatizado', 'atendimento via whatsapp',
  'horário de atendimento', 'horario de atendimento',
  'digite 1', 'pressione 1', 'opção 1', 'opcao 1',
  // 06/11/2026: menus e assistentes virtuais (Anami, Biostévi passaram batido)
  'assistente virtual', 'atendente virtual', 'assistente digital',
  'selecione uma opç', 'selecione uma opc', 'escolha uma opç', 'escolha uma opc',
  'uma das opções', 'uma das opcoes', 'agradece seu contato', 'agradece o seu contato',
  'para agilizar seu atendimento', 'para agilizar o seu atendimento'
];
// IA da Meta atendendo pela empresa: conversa de verdade, em nome do dono (sem marca no payload do WAHA)
const sinaisIA = [
  /verificar (a )?(agenda|disponibilidade)/, /confirmar (a )?disponibilidade/,
  /me conta (um )?(pouco|pouquinho|mais)/, /qual (é )?a sua (ideia|proposta)/,
  /te conhecer melhor/, /encaminhar/, /repassar/, /passar (o )?recado/, /anotad[oa]|anotei/
];
// uma saída por lead: agrupa as mensagens pela conversa do lead
return leads.map(lead => {
  const ms = msgs.filter(m => m.conversation_id === lead.conversation_id);
  const textos = ms.map(m => String(m.body || '').toLowerCase()).join(' ');
  const padraoRobo = keywords.some(k => textos.includes(k));
  const envioTs = lead.mensagem1_enviada_em ? new Date(lead.mensagem1_enviada_em).getTime() : 0;
  const ultraRapida = ms.some(m => {
    const ts = m.created_at ? new Date(m.created_at).getTime() : 0;
    return ts > 0 && envioTs > 0 && (ts - envioTs) < 8000;
  });
  const primeiraTs = (ms.length && ms[0].created_at) ? new Date(ms[0].created_at).getTime() : 0;
  const atrasoSeg = (primeiraTs > 0 && envioTs > 0) ? Math.round((primeiraTs - envioTs) / 1000) : null;
  const sinais = sinaisIA.filter(r => r.test(textos));
  const jaSimulada = !!(((lead._custom_fields_raw || {}).wf01 || {}).ia_meta_simulada_em);
  const iaMeta = !jaSimulada && atrasoSeg !== null && atrasoSeg <= 90 && sinais.length >= 2;
  return { json: Object.assign({}, lead, {
    robo_detectado: padraoRobo || ultraRapida,
    robo_motivo: padraoRobo ? 'padrao_texto' : (ultraRapida ? 'resposta_ultra_rapida' : 'nao_detectado'),
    robo_texto_resposta: textos.substring(0, 300),
    robo_qtd_respostas: ms.length,
    ia_meta_detectada: iaMeta,
    ia_meta_atraso_seg: atrasoSeg,
    ia_meta_motivo: 'resposta_em_' + atrasoSeg + 's_sinais_' + sinais.length
  }) };
});

const lead = $('Code - Detectar Robô').item.json;
const atual = $json || {};
// custom_fields FRESCO do banco, para não apagar campos gravados depois do início da execução
const cf = (atual.custom_fields && typeof atual.custom_fields === 'object') ? atual.custom_fields : {};
const prev = cf.wf01 || {};
const NL = String.fromCharCode(10);
const nota = '[' + new Date().toISOString() + '] WF01b: robo detectado apos envio (checagem desacoplada). Motivo: ' + (lead.robo_motivo || '') + '. Texto recebido: ' + (lead.robo_texto_resposta || '');
const novo = Object.assign({}, cf, {
  wf01: Object.assign({}, prev, {
    status: 'robo_detectado',
    etapa: 'aguardando_humano',
    bloqueado: true,
    motivo_bloqueio: 'robo_detectado_resposta_automatica',
    observacoes: ((prev.observacoes || '') + NL + nota).trim()
  })
});
return { json: Object.assign({}, lead, { patch_body: JSON.stringify({ custom_fields: novo }) }) };

const MODO = 'simulacao'; // 'simulacao' = so mostra o texto ao Hamilton | 'producao' = envia ao lead
const lead = $('Montar Bloqueio Robô').first().json;
const envio = $json || {};
const bloq = $('Bloquear Lead Robô (CRM)').first().json || {};
const cf = (bloq.custom_fields && typeof bloq.custom_fields === 'object') ? bloq.custom_fields : {};
const wf = cf.wf01 || {};
const corpo = String(envio.body || '');
const partes = corpo.split(/\n\s*\n/);
// formato com linha em branco: pergunta = tudo após a 1ª linha em branco
let pergunta = (partes.length > 1 ? partes.slice(1).join(' ') : '').replace(/\s+/g, ' ').trim();
if (!pergunta) {
  // variantes de um parágrafo só (ex.: CASAMENTO_B): "... Dúvida rápida: <pergunta>? ..."
  const m = corpo.replace(/\s+/g, ' ').match(/d[úu]vida r[áa]pida:\s*([^?]*\?)/i);
  if (m) pergunta = m[1].replace(/\s*\([^)]*\)/g, '').trim();
  pergunta = pergunta.charAt(0).toUpperCase() + pergunta.slice(1);
}
const empresa = String(lead.nome || lead.negocio || '').trim();
let tel = String(lead.telefone_normalizado || '').replace(/\D/g, '');
if (tel && !tel.startsWith('55')) tel = '55' + tel;
const brt = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const min = brt.getHours() * 60 + brt.getMinutes();
const dentroJanela = (min >= 540 && min <= 710) || (min >= 840 && min <= 1070);
let motivo = '';
if (wf.robo_resposta_enviada_em) motivo = 'ja_enviada';
else if (!pergunta) motivo = 'sem_pergunta';
else if (!tel) motivo = 'sem_telefone';
else if (MODO === 'producao' && !dentroJanela) motivo = 'fora_da_janela';
else if (MODO === 'producao' && !envio.channel_session_id) motivo = 'sem_canal';
const saud = empresa ? 'Oi, ' + empresa + '!' : 'Oi!';
// curta, repete a oferta original, sem apontar defeito no atendimento do lead (versão de 03/11/2026)
const perguntaMin = pergunta.charAt(0).toLowerCase() + pergunta.slice(1);
const msg_b = saud + ' Aqui é o Hamilton, da Agência OnlineAgora. Vi que minha mensagem caiu no automático 🙂 Quando alguém puder, me conta: ' + perguntaMin;
return { json: { modo: MODO, pode_enviar: motivo === '', motivo_skip: motivo, msg_b, chatId: tel + '@c.us', telefone: tel, empresa, pergunta, lead_id: lead.lead_id, contact_id: lead.contact_id, conversation_id: lead.conversation_id, channel_session_id: envio.channel_session_id || null } };

const m = $('Montar Mensagem B').first().json;
const bloq = $('Bloquear Lead Robô (CRM)').first().json || {};
const cf = (bloq.custom_fields && typeof bloq.custom_fields === 'object') ? bloq.custom_fields : {};
const prev = cf.wf01 || {};
const NL = String.fromCharCode(10);
const agora = new Date().toISOString();
const nota = '[' + agora + '] WF01b: mensagem B enviada ao lead (resposta ao robo). Texto: ' + m.msg_b;
const novo = Object.assign({}, cf, { wf01: Object.assign({}, prev, { robo_resposta_enviada_em: agora, robo_resposta_texto: m.msg_b, observacoes: ((prev.observacoes || '') + NL + nota).trim() }) });
return { json: { lead_id: m.lead_id, patch_body: JSON.stringify({ custom_fields: novo }) } };

const lead = $('IF - IA da Meta?').item.json;
const atual = $json || {};
// custom_fields FRESCO do banco; se a leitura falhar, usa o da execução (nunca grava um objeto vazio por cima)
const base = (atual.custom_fields && typeof atual.custom_fields === 'object') ? atual.custom_fields : (lead._custom_fields_raw || {});
const prev = base.wf01 || {};
const NL = String.fromCharCode(10);
const agora = new Date().toISOString();
const nota = '[' + agora + '] WF01b (SIMULACAO): possivel IA da Meta respondendo pela empresa. ' + lead.ia_meta_motivo + '. Nenhum bloqueio e nenhuma mensagem enviada ao lead.';
const novo = Object.assign({}, base, { wf01: Object.assign({}, prev, { ia_meta_simulada_em: agora, ia_meta_motivo: lead.ia_meta_motivo, observacoes: ((prev.observacoes || '') + NL + nota).trim() }) });
return { json: Object.assign({}, lead, { patch_body: JSON.stringify({ custom_fields: novo }) }) };

const MODO = 'simulacao'; // so mostra o texto ao Hamilton; nao ha ramo de envio ao lead neste fluxo
const CONTATO_FONE = '<TELEFONE_HAMILTON_FORMATADO>';
const CONTATO_EMAIL = '<EMAIL_HAMILTON>';
const l = $('IF - IA da Meta?').item.json;
const wf = ((l._custom_fields_raw || {}).wf01) || {};
const variante = String(wf.variante_mensagem || '');
const empresa = String(l.nome || l.negocio || '').trim();
const saud = empresa ? 'Oi, ' + empresa + '!' : 'Oi!';
let msg_c = '';
let motivo_skip = '';
if (/^CASAMENTO/i.test(variante)) {
  msg_c = saud + ' Sobre a ideia que comentei: eu ajudo cerimonialistas a receber mais pedidos de orçamento de noivas pelo Instagram e WhatsApp. Não é parceria de fornecedor nem envio de portfólio. Queria 10 minutos com quem cuida de captar noivas por aí, pra mostrar como funciona. Pra retornarem, podem usar este número: ' + CONTATO_FONE + ', ou o e-mail ' + CONTATO_EMAIL + '. Hamilton, da Agência OnlineAgora.';
} else {
  motivo_skip = 'sem_modelo_para_variante_' + (variante || 'vazia');
}
return { json: Object.assign({}, l, { modo_c: MODO, msg_c, motivo_skip_c: motivo_skip }) };

// guarda a mensagem B no lead com um token de uso unico; o link do WF01c usa esse token pra enviar pelo 2144
const m = $json;
const bloq = $('Bloquear Lead Robô (CRM)').first().json || {};
const cf = (bloq.custom_fields && typeof bloq.custom_fields === 'object') ? bloq.custom_fields : {};
const prev = cf.wf01 || {};
let token = '';
while (token.length < 32) token += Math.random().toString(36).slice(2);
token = token.slice(0, 32);
const pend = { token, texto: m.msg_b, chatId: m.chatId, telefone: m.telefone, empresa: m.empresa, conversation_id: m.conversation_id, channel_session_id: m.channel_session_id, contact_id: m.contact_id, criado_em: new Date().toISOString() };
const novo = Object.assign({}, cf, { wf01: Object.assign({}, prev, { msg_b_pendente: pend }) });
const link = 'https://webhook.hamiltonviana.com.br/webhook/wf01b-enviar-b?lead=' + m.lead_id + '&t=' + token;
return { json: Object.assign({}, m, { link_envio: link, patch_body: JSON.stringify({ custom_fields: novo }) }) };
